import{_ as a,o as i,c as t,a5 as o}from"./chunks/framework.CsGesDJn.js";const l=JSON.parse('{"title":"Sequence Flow — Approve Media Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-6-approve-media-campaign/sequence-flow.md","filePath":"feature/media-package-campaign/3-5-6-approve-media-campaign/sequence-flow.md"}'),c={name:"feature/media-package-campaign/3-5-6-approve-media-campaign/sequence-flow.md"};function d(n,e,r,m,p,g){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="sequence-flow-—-approve-media-campaign" tabindex="-1">Sequence Flow — Approve Media Campaign <a class="header-anchor" href="#sequence-flow-—-approve-media-campaign" aria-label="Permalink to &quot;Sequence Flow — Approve Media Campaign&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.5.6). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those).</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User (Client / Manager)</strong> — actor tương tác chính trong quy trình.</li><li><strong>Client</strong> — giao diện người dùng <code>MediaCampaignUI</code>.</li><li><strong>System</strong> — <code>MediaCampaignController</code> / <code>MediaCampaignService</code>.</li></ul><hr><h2 id="flow-a-—-luong-thuc-thi-chinh-approve-media-campaign" tabindex="-1">Flow A — Luồng thực thi chính: Approve Media Campaign <a class="header-anchor" href="#flow-a-—-luong-thuc-thi-chinh-approve-media-campaign" aria-label="Permalink to &quot;Flow A — Luồng thực thi chính: Approve Media Campaign&quot;">​</a></h2><ol><li>userclientmanager -&gt; mediacampaignui: <code>reviews campaign work items &amp; clicks &quot;Approve Campaign&quot;</code></li><li>mediacampaignservice -&gt; mediacampaignservice: <code>set approvedByClientAt = now</code></li><li>mediacampaignservice -&gt; mediacampaignservice: <code>set approvedByAgencyAt = now</code></li><li>mediacampaignservice -&gt; mediacampaignservice: <code>set status = IN_PROGRESS</code></li><li>mediacampaignui -&gt; mediacampaigncontrol: <code>POST /api/v1/media-campaigns/{campaignId}/approve</code></li><li>mediacampaigncontrol -&gt; mediacampaignservice: <code>approveCampaign(campaignId, currentUser)</code></li><li>mediacampaignservice -&gt; mediacampaignreposit: <code>findByIdForUpdate(campaignId)</code></li><li>mediacampaignreposit --&gt; mediacampaignservice: <code>campaign</code></li><li>mediacampaignservice --&gt; mediacampaigncontrol: <code>throw BusinessException (404 CAMPAIGN_NOT_FOUND)</code></li><li>mediacampaigncontrol --&gt; mediacampaignui: <code>404 Not Found (CAMPAIGN_NOT_FOUND)</code></li><li>mediacampaignui --&gt; userclientmanager: <code>show error toast (&#39;Campaign not found&#39;)</code></li><li>mediacampaignservice --&gt; mediacampaigncontrol: <code>throw BusinessException (400 CAMPAIGN_ALREADY_ACTIVE)</code></li><li>mediacampaigncontrol --&gt; mediacampaignui: <code>400 Bad Request (CAMPAIGN_ALREADY_ACTIVE)</code></li><li>mediacampaignui --&gt; userclientmanager: <code>show error toast (&#39;Campaign is already in progress or completed&#39;)</code></li><li>mediacampaignservice --&gt; mediacampaigncontrol: <code>throw BusinessException (403 WORKSPACE_ACCESS_DENIED)</code></li><li>mediacampaigncontrol --&gt; mediacampaignui: <code>403 Forbidden (WORKSPACE_ACCESS_DENIED)</code></li><li>mediacampaignui --&gt; userclientmanager: <code>show error toast (&#39;Access denied: Client or Agency Manager role required&#39;)</code></li><li>mediacampaignservice -&gt;&gt; mediacampaignreposit: <code>save(campaign)</code></li><li>mediacampaignreposit --&gt; mediacampaignservice: <code>savedCampaign</code></li><li>mediacampaignservice --&gt; mediacampaigncontrol: <code>MediaCampaignResponse (approved timestamp recorded)</code></li><li>mediacampaigncontrol --&gt; mediacampaignui: <code>200 OK (partially approved)</code></li><li>mediacampaignui --&gt; userclientmanager: <code>show toast (&#39;Approval recorded. Awaiting confirmation from second party&#39;)</code></li><li>mediacampaignservice -&gt;&gt; taskrepositorymongod: <code>upsertTask({campaignId, campaignWorkItemId: workItem.id}, taskData)</code></li><li>taskrepositorymongod --&gt; mediacampaignservice: <code>upsertedTaskDocument</code></li><li>mediacampaignservice -&gt;&gt; mediacampaignreposit: <code>save(campaign)</code></li><li>mediacampaignreposit --&gt; mediacampaignservice: <code>savedCampaign (status: IN_PROGRESS)</code></li><li>mediacampaignservice --&gt; mediacampaigncontrol: <code>MediaCampaignResponse (status: IN_PROGRESS)</code></li><li>mediacampaigncontrol --&gt; mediacampaignui: <code>200 OK (MediaCampaignResponse)</code></li><li>mediacampaignui --&gt; userclientmanager: <code>show success modal (&#39;Campaign fully approved! Work items deployed to Task Backlog&#39;)</code></li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>Xác thực</td><td>Token thiếu, hết hạn hoặc không hợp lệ</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>Phân quyền</td><td>Vai trò người dùng không có quyền truy cập tính năng</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Kiểm tra dữ liệu</td><td>Dữ liệu đầu vào không hợp lệ hoặc xung đột trạng thái</td><td>400</td><td><code>BAD_REQUEST</code></td></tr><tr><td>Truy vấn</td><td>Không tìm thấy bản ghi đối tượng tương ứng</td><td>404</td><td><code>NOT_FOUND</code></td></tr></tbody></table>',10)])])}const h=a(c,[["render",d]]);export{l as __pageData,h as default};
